import numpy as np
from scipy.optimize import least_squares
one=np.ones_like(t); L=np.log(P)
common=[P*L,one,t,P]
def mk(fam,p):
    if fam=='sin_exp': return [one/P,t*np.exp(-p[1]*t)/P,np.sin(p[0]*t)/P,np.cos(p[0]*t)/P]
    if fam=='sin1': return [one/P,t/P,np.sin(p[0]*t)/P,np.cos(p[0]*t)/P]
    if fam=='sin_t': return [one/P,t/P,t*np.sin(p[0]*t)/P,t*np.cos(p[0]*t)/P,np.sin(p[0]*t)/P,np.cos(p[0]*t)/P]
    if fam=='sin_sep': return [one/P,t/P,np.sin(p[0]*t)/P,np.cos(p[0]*t)/P,np.sin(p[1]*t)/P,np.cos(p[1]*t)/P]
    if fam=='exp_sin': return [one/P,t/P,np.exp(-p[1]*t)/P,np.sin(p[0]*t)/P,np.cos(p[0]*t)/P]
def rr(p,fam):
    A=np.column_stack(mk(fam,p)+common); c=np.linalg.lstsq(A,dP_dt,rcond=None)[0]
    return dP_dt-A@c
